# EXP-10B kernel validation (self-contained): 40 games, seeds 1-10 x 2 seats x 2 arms.
import base64, importlib.util, json, multiprocessing as mp, os, subprocess, sys

subprocess.run([sys.executable, "-m", "pip", "install", "-q",
                "kaggle-environments==1.32.7"], check=True)
import kaggle_environments
assert kaggle_environments.__version__ == "1.32.7"
from kaggle_environments import make

BASE = "/kaggle/working/agents"
os.makedirs(BASE, exist_ok=True)
FILES = {'closer_cleo.py': '', 'executed_ledger.py': '', 'v0_main.py': '', 'v1_frozen_sell.py': ''}
for name, blob in FILES.items():
    with open(os.path.join(BASE, name), "wb") as f:
        f.write(base64.b64decode(blob))
sys.path.insert(0, BASE)
import executed_ledger as EL


def run_one(task):
    arm, seed, seat = task
    def load(fn, tag):
        spec = importlib.util.spec_from_file_location(f"{fn}_{tag}", os.path.join(BASE, fn))
        m = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(m)
        return m.agent
    opp = load("closer_cleo.py", f"{seed}_{seat}")
    cand = load("v0_main.py" if arm == "V0" else "v1_frozen_sell.py", f"{arm}_{seed}_{seat}")
    a, b = (cand, opp) if seat == 0 else (opp, cand)
    env = make("kaggriculture", debug=False)
    env.configuration["episodeSteps"] = 720
    env.info["seed"] = seed
    env.run([a, b])
    steps = env.steps
    agg, valid, n, mism = EL.replay_game(steps, seat)
    final = steps[-1][seat]["observation"]["farms"][seat]["money"]
    rev = agg["SELL"][1]
    cost = sum(agg[t][1] for t in ("BUY_SEED", "BUY_PRODUCT", "BUY_ANIMAL", "HIRE", "BUY_LAND"))
    return {"arm": arm, "seed": seed, "seat": seat, "steps": len(steps),
            "recon": round(final - (EL.INITIAL_BANK + rev - cost), 4),
            "bank": round(float(final), 2), "sell_rev": round(float(rev), 2),
            "sell_exec": agg["SELL"][0], "sell_issued": agg["issued"]["SELL"]}


if __name__ == "__main__":
    tasks = [(a, s, st) for a in ("V0", "V1") for s in range(1, 11) for st in (0, 1)]
    with mp.Pool(4) as pool:
        results = list(pool.imap_unordered(run_one, tasks))
    results.sort(key=lambda r: (r["arm"], r["seed"], r["seat"]))
    for r in results:
        print(r["arm"], r["seed"], r["seat"], r["bank"], r["recon"], flush=True)
    with open("/kaggle/working/kernel_results.json", "w") as f:
        json.dump(results, f)
    bad = [r for r in results if r["steps"] != 720 or abs(r["recon"]) > 0.005]
    print(f"GATES failures = {len(bad)}")
    for arm in ("V0", "V1"):
        banks = [r["bank"] for r in results if r["arm"] == arm]
        print(f"{arm} mean bank {sum(banks)/len(banks):.0f}")
    print("KERNEL DONE")
